-- 0009 — the concept vocabulary refactor (2026-10-11).
--
-- The MeSH-derived vocabulary is replaced by generated concepts, each with a
-- card of Tier 1 (core) and Tier 2 (broader field) terms; Tier 3 is "any paper in
-- the concept's specialty" (ADR 0005, docs repo). The condition* table names are
-- kept; their contents are regenerated by `pex run vocabulary`. Nothing serves
-- these tables yet, so this is a replacement rather than a data migration.
--
-- **Touches serving tables — reconciled into the docs-repo DDL
-- (02-conditions.sql, 03-publications.sql, 06-features.sql) in the same change.**

-- condition_synonym: kinds become clinical / abbreviation / everyday. Specialty
-- words, symptoms, body parts and other conditions are no longer synonyms.
-- NOT VALID: the old MeSH-era rows (colloquial, body_part) are left in place
-- until the vocabulary loader replaces the whole vocabulary; every new row is
-- checked. The loader validates the constraint once the old rows are gone.
ALTER TABLE condition_synonym DROP CONSTRAINT IF EXISTS condition_synonym_kind_check;
ALTER TABLE condition_synonym ADD CONSTRAINT condition_synonym_kind_check
    CHECK (kind IN ('clinical', 'abbreviation', 'everyday')) NOT VALID;

-- condition_term: the card's Tier 1 and Tier 2 phrases, matched against paper
-- and trial titles at build time. Never read by search.
CREATE TABLE IF NOT EXISTS condition_term (
    condition_id  bigint NOT NULL REFERENCES condition (condition_id) ON DELETE CASCADE,
    term          text NOT NULL CHECK (term = lower(term)),
    tier          smallint NOT NULL CHECK (tier IN (1, 2)),
    -- The concept's own names (its name and aliases). A Tier 1 paper whose title
    -- contains one of these earns the exact-name bonus.
    is_name       boolean NOT NULL DEFAULT false,
    PRIMARY KEY (condition_id, term)
);

-- condition_link: how concepts relate. Keeps cards consistent with each other
-- (UPJ obstruction ↔ pyeloplasty), drives "related searches" chips, and backs the
-- same-specialty check for two-topic queries.
CREATE TABLE IF NOT EXISTS condition_link (
    from_id   bigint NOT NULL REFERENCES condition (condition_id) ON DELETE CASCADE,
    to_id     bigint NOT NULL REFERENCES condition (condition_id) ON DELETE CASCADE,
    relation  text NOT NULL CHECK (relation IN ('treated_by', 'treats', 'broader', 'related')),
    PRIMARY KEY (from_id, to_id, relation),
    CHECK (from_id <> to_id)
);
CREATE INDEX IF NOT EXISTS condition_link_to ON condition_link (to_id);

-- condition_mesh: which tier a MeSH-tagged paper lands in when its title misses
-- the card's terms. is_primary stays for compatibility.
ALTER TABLE condition_mesh
    ADD COLUMN IF NOT EXISTS tier smallint NOT NULL DEFAULT 2 CHECK (tier IN (1, 2));

-- specialty_field: NUCC specialty ↔ OpenAlex subfield, so "any paper in this
-- specialty" (Tier 3) is a lookup on a paper's topics rather than a text match.
CREATE TABLE IF NOT EXISTS specialty_field (
    taxonomy_code         text NOT NULL REFERENCES taxonomy (code),
    openalex_subfield_id  text NOT NULL,      -- e.g. '2748' (Urology)
    subfield_name         text NOT NULL,
    PRIMARY KEY (taxonomy_code, openalex_subfield_id)
);

-- physician_condition_features: the tier × author-role cross-tab the ranking
-- formula consumes (backend/ranking-formula.md). relevant_pub_count and
-- first_last_pub_count keep their meaning as Tier 1 + Tier 2 totals.
ALTER TABLE physician_condition_features
    ADD COLUMN IF NOT EXISTS tier1_fl_pub_count       integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier1_mid_pub_count      integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier1_name_fl_pub_count  integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier1_name_mid_pub_count integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier2_fl_pub_count       integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier2_mid_pub_count      integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier3_fl_pub_count       integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier3_mid_pub_count      integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier1_trial_count        integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS tier2_trial_count        integer NOT NULL DEFAULT 0;

-- authorship: the author's institutions as printed on this paper, captured by the
-- works pass. The per-paper filter uses them to split OpenAlex profiles that merge
-- several same-name people, and records why a paper was set aside rather than
-- deleting it, so the filter can be re-tuned without another works pass.
ALTER TABLE authorship
    ADD COLUMN IF NOT EXISTS institution_ids  jsonb NOT NULL DEFAULT '[]'::jsonb,
    ADD COLUMN IF NOT EXISTS country_codes    jsonb NOT NULL DEFAULT '[]'::jsonb,
    ADD COLUMN IF NOT EXISTS excluded_reason  text;

CREATE INDEX IF NOT EXISTS authorship_npi_included
    ON authorship (npi) WHERE excluded_reason IS NULL;
